using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Security.Cryptography;using System.Text;using Newtonsoft.Json.Linq;using ICSharpCode.SharpZipLib.Zip;
namespace JonsboStudio {
 sealed class ThemeEntry {public string id,name,path,thumbnail,source;public int width,height;}
 static class ThemeRepository {
  public const string ArchivePassword="vmax2025";
  public static string Id(string value){using(var hash=SHA256.Create())return BitConverter.ToString(hash.ComputeHash(Encoding.UTF8.GetBytes(value))).Replace("-","").Substring(0,20).ToLowerInvariant();}
  public static List<ThemeEntry> Scan(){
   var paths=new List<string>();foreach(string folder in new[]{Path.Combine(AppPaths.Installed,"Programme"),Path.Combine(AppPaths.Installed,"ThemeScheme"),Path.Combine(AppPaths.Installed,"Skin"),AppPaths.Data("Themes")})if(Directory.Exists(folder))paths.AddRange(Directory.GetFiles(folder,"*.json",SearchOption.AllDirectories));
   var entries=new List<ThemeEntry>();foreach(string path in paths.Distinct(StringComparer.OrdinalIgnoreCase))try{
    var json=JObject.Parse(File.ReadAllText(path));if(json["Width"]==null||json["Height"]==null||json["Name"]==null)continue;
    var item=new ThemeEntry{id=Id(path),name=(string)json["Name"],path=path,width=(int)json["Width"],height=(int)json["Height"],source=path.StartsWith(AppPaths.Root,StringComparison.OrdinalIgnoreCase)?"My library":"Installed JONSBO"};
    string preview=Path.Combine(Path.GetDirectoryName(path),"demo.png");if(!File.Exists(preview))preview=Path.Combine(Path.GetDirectoryName(path),"back.png");
    if(!File.Exists(preview)&&json["ThumbnailImageData"]!=null&&!string.IsNullOrWhiteSpace((string)json["ThumbnailImageData"])){preview=Path.Combine(AppPaths.Data("Thumbnails"),item.id+".png");if(!File.Exists(preview)){byte[] bytes=Convert.FromBase64String((string)json["ThumbnailImageData"]);if(bytes.Length<8*1024*1024)File.WriteAllBytes(preview,bytes);}}
    if(!File.Exists(preview)){string bundled=Path.Combine(AppPaths.Root,"Assets","ThemeThumbs",item.name+".png"),installed=Path.Combine(AppPaths.Installed,"Programme",item.name,"demo.png");if(File.Exists(bundled))preview=bundled;else if(File.Exists(installed))preview=installed;}
    if(!File.Exists(preview))try{preview=Path.Combine(AppPaths.Data("Thumbnails"),item.id+"-generated.jpg");if(!File.Exists(preview)){var document=ThemeDocument.Load(path);if(document.Video){var info=new System.Diagnostics.ProcessStartInfo(PlaybackEngine.Ffmpeg,"-hide_banner -loglevel error -nostdin -ss 0.5 -i \""+document.Background+"\" -frames:v 1 -vf \"scale=480:240:force_original_aspect_ratio=decrease\" -y \""+preview+"\""){UseShellExecute=false,CreateNoWindow=true};using(var process=System.Diagnostics.Process.Start(info))process.WaitForExit(10000);}else using(var renderer=new ThemeRenderer(document,0))File.WriteAllBytes(preview,renderer.Compose(null,new SensorSnapshot(),75));}}catch{}
    item.thumbnail=File.Exists(preview)?AppPaths.AssetUrl(preview):"";entries.Add(item);
   }catch{}
   return entries.GroupBy(x=>x.name+"|"+x.width+"|"+x.height).Select(g=>g.OrderByDescending(x=>x.source=="My library").ThenByDescending(x=>x.path.Contains("ThemeScheme")&&x.path.Contains("VMAX")).ThenByDescending(x=>x.thumbnail.Length>0).First()).OrderBy(x=>x.name,StringComparer.OrdinalIgnoreCase).ToList();
  }
  public static string Import(string path){
   string extension=Path.GetExtension(path).ToLowerInvariant();if(extension==".json")return SaveEditor(ThemeDocument.Load(path).ForEditor());
   if(extension!=".vmax"&&extension!=".jonsbo"&&extension!=".zip")throw new InvalidDataException("Choose a JONSBO .vmax, .JONSBO, .zip or .json theme.");
   string folder=Path.Combine(AppPaths.Data("Themes"),Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);long total=0;int entries=0;
   try{
    using(var stream=File.OpenRead(path))using(var zip=new ZipInputStream(stream)){zip.Password=ArchivePassword;ZipEntry entry;byte[] buffer=new byte[65536];while((entry=zip.GetNextEntry())!=null){if(++entries>4096)throw new InvalidDataException("Archive has too many entries.");string target=Path.GetFullPath(Path.Combine(folder,entry.Name.Replace('/',Path.DirectorySeparatorChar)));if(!target.StartsWith(folder+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Unsafe archive path.");if(entry.IsDirectory){Directory.CreateDirectory(target);continue;}Directory.CreateDirectory(Path.GetDirectoryName(target));using(var output=new FileStream(target,FileMode.CreateNew)){int count;while((count=zip.Read(buffer,0,buffer.Length))>0){total+=count;if(total>2L*1024*1024*1024)throw new InvalidDataException("Theme archive exceeds 2 GB.");output.Write(buffer,0,count);}}}}
    string json=Directory.GetFiles(folder,"*.json",SearchOption.AllDirectories).FirstOrDefault(x=>{try{return JObject.Parse(File.ReadAllText(x))["Width"]!=null;}catch{return false;}});if(json==null)throw new InvalidDataException("No JONSBO theme JSON found in the package.");
    var theme=ThemeDocument.Load(json);NormalizePaths(theme.Json,theme,folder,false);AppPaths.SaveJson(json,theme.Json);return json;
   }catch{if(Path.GetFullPath(folder).StartsWith(Path.GetFullPath(AppPaths.Data("Themes"))+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))Directory.Delete(folder,true);throw;}
  }
  static string CopyAsset(string value,ThemeDocument original,string folder,bool relative){string source=original.Resolve(value);if(!File.Exists(source))return value??"";string name=Path.GetFileName(source),target=Path.Combine(folder,name);if(!string.Equals(Path.GetFullPath(source),Path.GetFullPath(target),StringComparison.OrdinalIgnoreCase)){if(File.Exists(target)&&new FileInfo(target).Length!=new FileInfo(source).Length){name=Id(source).Substring(0,8)+"-"+name;target=Path.Combine(folder,name);}if(!File.Exists(target))File.Copy(source,target);}return relative?name:target;}
  static void NormalizePaths(JObject json,ThemeDocument original,string folder,bool relative){foreach(string field in new[]{"BackgroundImage","BackgroundVideoFile","OriginalBGPath"})if(json[field]!=null&&!string.IsNullOrWhiteSpace((string)json[field]))json[field]=CopyAsset((string)json[field],original,folder,relative);foreach(JObject image in ((json["DisplayImages"] as JArray)??new JArray()).OfType<JObject>()){string value=(string)image["Image"]??(string)image["ImageFileName"];string copied=CopyAsset(value,original,folder,relative);image["Image"]=copied;image["ImageFileName"]=Path.GetFileName(copied);image.Remove("url");}}
  public static string SaveEditor(JObject input){
   var json=(JObject)input.DeepClone();string oldPath=(string)json["filePath"]??"";ThemeDocument original;
   if(File.Exists(oldPath))original=ThemeDocument.Load(oldPath);else original=new ThemeDocument{Path="",Folder=AppPaths.Root,Json=json,Background=""};
   original.Json=json;string library=AppPaths.Data("Themes"),folder=File.Exists(oldPath)&&Path.GetFullPath(oldPath).StartsWith(library+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)?Path.GetDirectoryName(oldPath):Path.Combine(library,Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string fontRoot=Path.Combine(original.Folder,"font");if(Directory.Exists(fontRoot)&&!string.Equals(original.Folder,folder,StringComparison.OrdinalIgnoreCase))CopyFolder(fontRoot,Path.Combine(folder,"font"));
   foreach(string field in new[]{"filePath","backgroundUrl","backgroundIsVideo","warning"})json.Remove(field);
   json["Width"]=Math.Max(16,Math.Min(3840,(int?)json["Width"]??1920));json["Height"]=Math.Max(16,Math.Min(2400,(int?)json["Height"]??462));
   NormalizePaths(json,original,folder,false);string name=(string)json["Name"]??"Untitled";string filename=new string(name.Select(c=>Path.GetInvalidFileNameChars().Contains(c)?'_':c).ToArray());if(filename.Length==0)filename="Untitled";string target=Path.Combine(folder,filename+".json");AppPaths.SaveJson(target,json);return target;
  }
  public static void Export(string path,string target){
   var theme=ThemeDocument.Load(path);string folder=Path.Combine(AppPaths.Data("Temp"),Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);
   try{var json=(JObject)theme.Json.DeepClone();NormalizePaths(json,theme,folder,true);if((int?)json["Type"]==1){string setting=theme.FindFile("Setting.txt");if(File.Exists(setting))File.Copy(setting,Path.Combine(folder,"Setting.txt"));foreach(string sub in new[]{"font","source"}){string source=Path.Combine(theme.Folder,sub);if(Directory.Exists(source))CopyFolder(source,Path.Combine(folder,sub));}}else{BakeShapes(json,folder);string fonts=Path.Combine(theme.Folder,"font");if(Directory.Exists(fonts))CopyFolder(fonts,Path.Combine(folder,"font"));}
    string safeName=new string(theme.Name.Select(c=>Path.GetInvalidFileNameChars().Contains(c)?'_':c).ToArray());if(string.IsNullOrWhiteSpace(safeName))safeName="Theme";AppPaths.SaveJson(Path.Combine(folder,safeName+".json"),json);
    string part=target+".part";try{using(var output=File.Create(part))using(var zip=new ZipOutputStream(output)){zip.SetLevel(3);zip.Password=ArchivePassword;foreach(string file in Directory.GetFiles(folder,"*",SearchOption.AllDirectories)){if(file.EndsWith(".bak"))continue;var entry=new ZipEntry(file.Substring(folder.Length+1).Replace('\\','/')){DateTime=DateTime.Now,Size=new FileInfo(file).Length};zip.PutNextEntry(entry);using(var source=File.OpenRead(file))source.CopyTo(zip);zip.CloseEntry();}zip.Finish();}if(File.Exists(target))File.Replace(part,target,null);else File.Move(part,target);}finally{if(File.Exists(part))File.Delete(part);}
   }finally{Directory.Delete(folder,true);}
  }
  public static string Remove(string path){string root=Path.GetFullPath(AppPaths.Data("Themes"));string full=Path.GetFullPath(path);if(!full.StartsWith(root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Installed themes are read-only. Save a copy to your library first.");string directory=Path.GetDirectoryName(full),target=Path.Combine(AppPaths.Data("Removed"),DateTime.UtcNow.ToString("yyyyMMddHHmmss")+"-"+Guid.NewGuid().ToString("N"));Directory.Move(directory,target);return target;}
  static void CopyFolder(string source,string target){foreach(string file in Directory.GetFiles(source,"*",SearchOption.AllDirectories)){string destination=Path.Combine(target,file.Substring(source.Length+1));Directory.CreateDirectory(Path.GetDirectoryName(destination));if(!File.Exists(destination))File.Copy(file,destination);}}
  static void BakeShapes(JObject json,string folder){var shapes=json["EnhancedShapes"] as JArray;if(shapes==null||shapes.Count==0)return;var images=json["DisplayImages"] as JArray??new JArray();foreach(var group in shapes.OfType<JObject>().GroupBy(x=>(int?)x["z"]??0)){string name="studio-shapes-"+group.Key+".png";using(var bitmap=new System.Drawing.Bitmap((int)json["Width"],(int)json["Height"],System.Drawing.Imaging.PixelFormat.Format32bppArgb)){using(var graphics=System.Drawing.Graphics.FromImage(bitmap)){graphics.Clear(System.Drawing.Color.Transparent);foreach(var shape in group)using(var brush=new System.Drawing.SolidBrush(ThemeDocument.ParseColor((string)shape["color"])))graphics.FillRectangle(brush,(float?)shape["x"]??0,(float?)shape["y"]??0,(float?)shape["width"]??100,(float?)shape["height"]??2);}bitmap.Save(Path.Combine(folder,name),System.Drawing.Imaging.ImageFormat.Png);}images.Add(new JObject{{"Left",0},{"Top",0},{"ZIndex",group.Key},{"Width",json["Width"]},{"Height",json["Height"]},{"Image",name},{"ImageFileName",name}});}json["DisplayImages"]=images;json.Remove("EnhancedShapes");}
 }
}
